const NAMES = ['class', 'await', 'function', 'const', 'return', 'a-b', 'a_b', 'workers-api', 'workers_api', H];

const chain = (label: string) => {
  const resource: Record<string, unknown> = {
    withEnvironment: (k: string, v: unknown) => (rec(`${label}.withEnvironment`, k, v), resource),
    withHttpHealthCheck: (o: unknown) => (rec(`${label}.withHttpHealthCheck`, o), resource),
    waitForCompletion: (o: unknown) => (rec(`${label}.waitForCompletion`, o), resource),
    withEndpoint: (o: unknown) => (rec(`${label}.withEndpoint`, o), resource),
    withContainerRuntimeArgs: (a: unknown) => resource,
    withArgs: (a: unknown) => resource,
    withBindMount: (...a: unknown[]) => resource,
    withDataBindMount: (...a: unknown[]) => resource,
    withLifetime: (...a: unknown[]) => resource,
    withImage: (...a: unknown[]) => resource,
    withImageTag: (...a: unknown[]) => resource,
    withHealthCheck: (...a: unknown[]) => resource,
    addDatabase: async (n: string) => (rec(`${label}.addDatabase`, n), resource),
    getEndpoint: async (p: string) => (rec(`${label}.getEndpoint`, p), { property: () => 'http://stub', host: async () => 'h', port: async () => 1 }),
  };
  return resource;
};
const builder = {
  addExecutable: (name: string, cmd: string, wd: string, args: string[]) => (rec('addExecutable', name, cmd, wd, args), chain(`exec:${name}`)),
  addParameter: async (name: string, opts: unknown) => (rec('addParameter', name, opts), chain(`param:${name}`)),
  addConnectionString: async (name: string) => (rec('addConnectionString', name), chain(`cs:${name}`)),
  addContainer: (name: string, image: string) => (rec('addContainer', name, image), chain(`container:${name}`)),
  addHealthCheck: (key: string, fn: unknown) => (rec('addHealthCheck', key), fn),
};
const config = {
  Version: 'test',
  Apps: Object.fromEntries(NAMES.map((n) => [n, { Enabled: true }])),
  Plugins: Object.fromEntries(NAMES.map((n) => [n, { Enabled: true }])),
  Tools: Object.fromEntries(NAMES.map((n) => [n, { Enabled: true }])),
};
const calls: unknown[][] = [];
const rec = (...args: unknown[]) => (calls.push(args), args[1] ?? args[0]);
globalThis.__COMPAT_CALLS = calls;

let failures = 0;
const expect = (cond: boolean, msg: string) => {
  if (!cond) {
    failures++;
    console.log(`  FAIL: ${msg}`);
  }
};

const check = (label: string, result: Map<string, unknown> | void) => {
  const addExec = calls.filter((c) => c[0] === 'addExecutable');
  const addParam = calls.filter((c) => c[0] === 'addParameter');
  const addContainer = calls.filter((c) => c[0] === 'addContainer');
  const addCs = calls.filter((c) => c[0] === 'addConnectionString');
  const all: unknown[][] = [...addExec, ...addParam, ...addContainer, ...addCs];
  // every registered resource name must round-trip byte-identical
  for (const name of NAMES) {
    expect(
      all.some((c) => c[1] === name),
      `${label}: hostile name not found byte-identical among registered resources`,
    );
  }
  // no stub received a corrupted literal (escaped twice / interpolated / truncated)
  for (const c of all) {
    for (const arg of c.slice(1)) {
      if (typeof arg === 'string' && arg.includes('value}')) {
        expect(arg === H, `${label}: literal corruption in stub arg ${JSON.stringify(arg)}`);
      }
    }
  }
  expect(!calls.some((c) => c.some((a) => a === 'value' || a === '\\nline')), `${label}: template interpolation leaked`);
  if (result instanceof Map) {
    for (const name of NAMES) expect(result.has(name), `${label}: result map missing ${JSON.stringify(name.slice(0, 12))}`);
  }
  console.log(`${label}: executed, ${all.length} resources registered, ${calls.length} stub calls, ${failures} failures so far`);
  calls.length = 0;
  globalThis.__COMPAT_CALLS = calls;
};

// --- apps ---
const { registerApps } = await import('./apps.mts');
check('apps', await registerApps(builder, config, {}, new Map(), new Map(), '/host'));

// --- plugins ---
const { registerPlugins } = await import('./plugins.mts');
check('plugins', await registerPlugins(builder, config, {}, new Map([['x', chain('svc')]]), '/host'));

// --- tools ---
const { registerTools } = await import('./tools.mts');
check('tools', await registerTools(builder, config, {}, '/host'));

// --- infrastructure ---
const { registerInfrastructure } = await import('./infrastructure.mts');
const infra = await registerInfrastructure(builder, config, '/host');
check('infrastructure', infra.databases as Map<string, unknown>);
const wiring = infra.cacheWiring as Map<string, unknown>;
for (const name of NAMES) expect(wiring.has(name), `infrastructure: cacheWiring missing ${JSON.stringify(name.slice(0, 12))}`);

console.log(failures === 0 ? 'EXECUTION VERDICT: PASS — all emitted modules ran, all hostile literals intact' : `EXECUTION VERDICT: FAIL — ${failures} assertion(s) failed`);
Deno.exit(failures === 0 ? 0 : 1);

